package org.apache.commons.math.ode.events;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.ConvergenceException;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.analysis.solvers.BrentSolver;
import org.apache.commons.math.exception.EventException;
import org.apache.commons.math.exception.FunctionEvaluationException;
import org.apache.commons.math.ode.DerivativeException;
import org.apache.commons.math.ode.events.EventState.EventHandler;
import org.apache.commons.math.ode.events.EventState.StepInterpolator;
import org.apache.commons.math.ode.sampling.StepInterpolator;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.*;

public class EventState_evaluateStep_TriageGen4Test {

    private EventState eventState;
    private double maxCheckInterval = 1.0;
    private double convergence = 1e-6;
    private int maxIterationCount = 100;

    @Mock
    private EventHandler handler;

    @Mock
    private StepInterpolator interpolator;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        eventState = new EventState(handler, maxCheckInterval, convergence, maxIterationCount);

        // Initialize internal state via reinitializeBegin to set t0 and g0
        // Since we can't access private fields directly, we use the public API
        // to set the initial conditions of the EventState.
        eventState.reinitializeBegin(0.0, new double[]{1.0});

        // We need to mock the handler.g to simulate the initial g0
        // The constructor/reinitialize sets g0 = handler.g(t0, y0)
        when(handler.g(eq(0.0), any(double[].class))).thenReturn(1.0);
    }

    @Test
    public void testEvaluateStep_NoEvent() throws Exception {
        when(interpolator.isForward()).thenReturn(true);
        when(interpolator.getCurrentTime()).thenReturn(1.0);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{1.0});

        // g(t) remains positive: 1.0 -> 1.0
        when(handler.g(anyDouble(), any(double[].class))).thenReturn(1.0);

        boolean eventDetected = eventState.evaluateStep(interpolator);

        assertFalse("Event should not be detected", eventDetected);
        assertEquals("Event time should be NaN", Double.NaN, eventState.getEventTime(), 1e-9);
    }

    @Test
    public void testEvaluateStep_EventDetected() throws Exception {
        when(interpolator.isForward()).thenReturn(true);
        when(interpolator.getCurrentTime()).thenReturn(1.0);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{1.0});

        // g0 is 1.0 (from setup). We make g(1.0) = -1.0 to trigger sign change
        // The loop calculates n based on (t1 - t0) / maxCheckInterval
        // t1=1.0, t0=0.0, maxCheckInterval=1.0 => n=1
        // tb will be 0.0 + convergence + 1.0 = 1.0 + convergence
        // We need a sign change between t=0 and t=1.0
        when(handler.g(anyDouble(), any(double[].class))).thenReturn(1.0, -1.0);

        boolean eventDetected = eventState.evaluateStep(interpolator);

        assertTrue("Event should be detected", eventDetected);
    }

    @Test
    public void testEvaluateStep_PendingEventTrue() throws Exception {
        // Setup: simulate a state where pendingEvent is already true
        // This is hard to do via public API, so we rely on the logic flow
        // If we trigger an event, pendingEvent becomes true.

        when(interpolator.isForward()).thenReturn(true);
        when(interpolator.getCurrentTime()).thenReturn(1.0);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{1.0});
        when(handler.g(anyDouble(), any(double[].class))).thenReturn(1.0, -1.0);

        eventState.evaluateStep(interpolator); // First call sets pendingEvent = true

        // Second call: trigger event at the exact same time
        // This tests: if (pendingEvent && (Math.abs(t1 - pendingEventTime) <= convergence)) return false;
        when(interpolator.getCurrentTime()).thenReturn(1.0 + convergence/2.0);
        // We need to ensure the solver finds the same root
        // For simplicity, we'll mock the return to trigger the "already found" branch
        // However, the solver is internal. We simulate by making the root close to previous.

        // Since we can't easily control BrentSolver root, we rely on the logic that 
        // if the event is already found, the step is accepted.
        // This is a complex branch to hit purely with mocks without a real solver.
    }

    @Test
    public void testEvaluateStep_DerivativeException() throws Exception {
        when(interpolator.isForward()).thenReturn(true);
        when(interpolator.getCurrentTime()).thenReturn(1.0);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{1.0});

        // Trigger sign change to enter the solver block
        when(handler.g(anyDouble(), any(double[].class))).thenReturn(1.0, -1.0);

        // Throw DerivativeException inside the UnivariateRealFunction
        doThrow(new DerivativeException(new RuntimeException())).when(handler).g(anyDouble(), any(double[].class));

        try {
            eventState.evaluateStep(interpolator);
        } catch (DerivativeException e) {
            // Success
        } catch (Exception e) {
            throw new AssertionError("Expected DerivativeException");
        }
    }

    @Test
    public void testEvaluateStep_EventException() throws Exception {
        when(interpolator.isForward()).thenReturn(true);
        when(interpolator.getCurrentTime()).thenReturn(1.0);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{1.0});

        // Trigger sign change
        when(handler.g(anyDouble(), any(double[].class))).thenReturn(1.0, -1.0);

        // Throw EventException inside the UnivariateRealFunction
        doThrow(new EventException(new RuntimeException())).when(handler).g(anyDouble(), any(double[].class));

        try {
            eventState.evaluateStep(interpolator);
        } catch (EventException e) {
            // Success
        } catch (Exception e) {
            throw new AssertionError("Expected EventException");
        }
    }

    @Test
    public void testEvaluateStep_FunctionEvaluationException_To_EventException() throws Exception {
        when(interpolator.isForward()).thenReturn(true);
        when(interpolator.getCurrentTime()).thenReturn(1.0);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{1.0});

        // Trigger sign change
        when(handler.g(anyDouble(), any(double[].class))).thenReturn(1.0, -1.0);

        // Throw a raw RuntimeException which gets wrapped in FunctionEvaluationException
        doThrow(new RuntimeException("Generic Error")).when(handler).g(anyDouble(), any(double[].class));

        try {
            eventState.evaluateStep(interpolator);
        } catch (EventException e) {
            // Success: FunctionEvaluationException is caught and rethrown as EventException
        } catch (Exception e) {
            throw new AssertionError("Expected EventException from FunctionEvaluationException");
        }
    }

    @Test
    public void testEvaluateStep_BackwardDirection() throws Exception {
        when(interpolator.isForward()).thenReturn(false);
        when(interpolator.getCurrentTime()).thenReturn(-1.0);
        when(interpolator.getInterpolatedState()).thenReturn(new double[]{1.0});

        // t0 = 0, t1 = -1. n = ceil(abs(-1-0)/1) = 1.
        // tb = t0 + (-convergence) + h = 0 - 1e-6 + (-1) = -1.000001
        // We need g0Positive ^ (gb >= 0)
        // Assume g0 = 1.0 (Positive). We need gb < 0.
        when(handler.g(anyDouble(), any(double[].class))).thenReturn(1.0, -1.0);

        boolean eventDetected = eventState.evaluateStep(interpolator);
        assertTrue(eventDetected);
    }
}
